package com.lifeos.goals;import com.lifeos.goals.dto.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.core.userdetails.UserDetails;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController@RequestMapping("/api/goals")public class GoalController{private final GoalService s;public GoalController(GoalService s){this.s=s;}@GetMapping public List<GoalResponse>list(@AuthenticationPrincipal UserDetails p){return s.list(p.getUsername());}@GetMapping("/{id}")public GoalResponse get(@PathVariable Long id,@AuthenticationPrincipal UserDetails p){return s.get(id,p.getUsername());}@PostMapping@ResponseStatus(HttpStatus.CREATED)public GoalResponse create(@Valid@RequestBody GoalRequest r,@AuthenticationPrincipal UserDetails p){return s.create(r,p.getUsername());}@PutMapping("/{id}")public GoalResponse update(@PathVariable Long id,@Valid@RequestBody GoalRequest r,@AuthenticationPrincipal UserDetails p){return s.update(id,r,p.getUsername());}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(@PathVariable Long id,@AuthenticationPrincipal UserDetails p){s.delete(id,p.getUsername());}}
